import React, { useState } from 'react';
import Layout from '../components/Layout';

const Candidates = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [scoreFilter, setScoreFilter] = useState('all');

  const [candidates] = useState([
    {
      id: '1',
      initials: 'JD',
      name: 'John Doe',
      email: 'john@example.com',
      position: 'Senior Developer',
      department: 'Engineering',
      matchScore: 92,
      skills: ['React', 'Node.js', 'Python', 'AWS'],
      status: 'shortlisted',
      uploadDate: '2026-05-05',
    },
    {
      id: '2',
      initials: 'JS',
      name: 'Jane Smith',
      email: 'jane@example.com',
      position: 'Full Stack Developer',
      department: 'Engineering',
      matchScore: 85,
      skills: ['Vue.js', 'Django', 'PostgreSQL', 'Docker'],
      status: 'interviewed',
      uploadDate: '2026-05-04',
    },
    {
      id: '3',
      initials: 'MJ',
      name: 'Mike Johnson',
      email: 'mike@example.com',
      position: 'Frontend Engineer',
      department: 'Engineering',
      matchScore: 78,
      skills: ['React', 'TypeScript', 'Tailwind CSS'],
      status: 'applied',
      uploadDate: '2026-05-03',
    },
    {
      id: '4',
      initials: 'SB',
      name: 'Sarah Brown',
      email: 'sarah@example.com',
      position: 'Product Manager',
      department: 'Product',
      matchScore: 88,
      skills: ['Product Strategy', 'Analytics', 'Agile'],
      status: 'shortlisted',
      uploadDate: '2026-05-02',
    },
    {
      id: '5',
      initials: 'DW',
      name: 'David Wilson',
      email: 'david@example.com',
      position: 'UX Designer',
      department: 'Design',
      matchScore: 81,
      skills: ['Figma', 'User Research', 'Prototyping'],
      status: 'interviewed',
      uploadDate: '2026-05-01',
    },
  ]);

  const getStatusColor = (status) => {
    switch (status) {
      case 'shortlisted':
        return { bg: 'bg-green-50', text: 'text-green-700', icon: 'check_circle', border: 'border-green-200' };
      case 'interviewed':
        return { bg: 'bg-blue-50', text: 'text-blue-700', icon: 'person', border: 'border-blue-200' };
      case 'rejected':
        return { bg: 'bg-red-50', text: 'text-red-700', icon: 'close', border: 'border-red-200' };
      default:
        return { bg: 'bg-slate-50', text: 'text-slate-700', icon: 'mail', border: 'border-slate-200' };
    }
  };

  const getScoreCategory = (score) => {
    if (score >= 85) return 'high';
    if (score >= 70) return 'medium';
    return 'low';
  };

  const filteredCandidates = candidates.filter((candidate) => {
    const matchesSearch =
      candidate.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      candidate.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
      candidate.position.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesStatus = statusFilter === 'all' || candidate.status === statusFilter;

    const matchesScore =
      scoreFilter === 'all' ||
      (scoreFilter === 'high' && candidate.matchScore >= 85) ||
      (scoreFilter === 'medium' && candidate.matchScore >= 70 && candidate.matchScore < 85) ||
      (scoreFilter === 'low' && candidate.matchScore < 70);

    return matchesSearch && matchesStatus && matchesScore;
  });

  return (
    <Layout title="Candidates">
      <div className="max-w-[1440px] mx-auto px-8 py-8 space-y-6">
        {/* Header Section */}
        <div className="flex items-start justify-between">
          <div>
            <h1 className="text-h1 font-h1 text-primary">Candidate Pool</h1>
            <p className="text-body-md text-secondary mt-1">
              Manage and evaluate all candidates across your recruitment pipeline ({filteredCandidates.length} results)
            </p>
          </div>
          <button className="px-4 py-2 bg-primary text-white rounded-lg text-sm font-semibold hover:opacity-90 transition-all flex items-center gap-2">
            <span className="material-symbols-outlined text-sm">add</span>
            Add Candidate
          </button>
        </div>

        {/* Search and Filters Bar */}
        <div className="bg-white rounded-xl border border-slate-200 p-4 shadow-sm space-y-4">
          <div className="relative">
            <span className="absolute left-4 top-1/2 transform -translate-y-1/2 material-symbols-outlined text-secondary text-xl">search</span>
            <input
              type="text"
              placeholder="Search by name, email, or position..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-12 pr-4 py-3 border border-slate-200 rounded-lg bg-white focus:ring-2 focus:ring-primary focus:border-transparent outline-none"
            />
          </div>

          {/* Filter Pills */}
          <div className="flex flex-wrap gap-3">
            <div className="flex items-center gap-2">
              <span className="text-label-sm text-secondary font-semibold">Status:</span>
              {['all', 'applied', 'shortlisted', 'interviewed', 'rejected'].map((status) => (
                <button
                  key={status}
                  onClick={() => setStatusFilter(status)}
                  className={`px-3 py-1 rounded-full text-label-sm font-semibold transition-all ${
                    statusFilter === status
                      ? 'bg-primary text-white'
                      : 'bg-slate-100 text-slate-700 hover:bg-slate-200'
                  }`}
                >
                  {status === 'all' ? 'All' : status.charAt(0).toUpperCase() + status.slice(1)}
                </button>
              ))}
            </div>

            <div className="flex items-center gap-2 ml-auto">
              <span className="text-label-sm text-secondary font-semibold">Match Score:</span>
              {['all', 'high', 'medium', 'low'].map((score) => (
                <button
                  key={score}
                  onClick={() => setScoreFilter(score)}
                  className={`px-3 py-1 rounded-full text-label-sm font-semibold transition-all ${
                    scoreFilter === score
                      ? 'bg-primary text-white'
                      : 'bg-slate-100 text-slate-700 hover:bg-slate-200'
                  }`}
                >
                  {score === 'all' ? 'All' : score === 'high' ? '85+' : score === 'medium' ? '70-84' : '<70'}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Candidates Table */}
        <div className="bg-white rounded-xl border border-slate-200 overflow-hidden shadow-sm">
          <table className="w-full">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 text-left font-label-sm text-label-sm text-secondary uppercase">Name</th>
                <th className="px-6 py-4 text-left font-label-sm text-label-sm text-secondary uppercase">Position</th>
                <th className="px-6 py-4 text-left font-label-sm text-label-sm text-secondary uppercase">Match Score</th>
                <th className="px-6 py-4 text-left font-label-sm text-label-sm text-secondary uppercase">Status</th>
                <th className="px-6 py-4 text-left font-label-sm text-label-sm text-secondary uppercase">Actions</th>
              </tr>
            </thead>
            <tbody>
              {candidates.map((candidate) => (
                <tr key={candidate.id} className="border-b border-slate-200 hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4">
                    <div>
                      <p className="font-medium text-slate-900">{candidate.name}</p>
                      <p className="text-sm text-slate-500">{candidate.email}</p>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-slate-700">{candidate.position}</td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <div className="w-16 bg-slate-200 rounded-full h-2 overflow-hidden">
                        <div
                          className="bg-green-500 h-full rounded-full"
                          style={{ width: `${candidate.matchScore}%` }}
                        ></div>
                      </div>
                      <span className="text-sm font-semibold text-slate-900">{candidate.matchScore}%</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`px-3 py-1 rounded-full text-xs font-semibold border ${getStatusColor(candidate.status)}`}>
                      {candidate.status.charAt(0).toUpperCase() + candidate.status.slice(1)}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <button className="text-primary hover:text-primary-container font-semibold text-sm">
                      View
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </Layout>
  );
};

export default Candidates;
